import * as http from 'node:http';
import { once } from 'node:events';
async function main(): Promise<void> {
  const upstream = http.createServer(async (req, res) => {
    if (req.url === '/sse') {
      res.writeHead(200, { 'content-type': 'text/event-stream', 'x-up': '1' });
      res.write('data: 1\n\n');
      await new Promise<void>((r) => setTimeout(() => r(), 20));
      res.write('data: 2\n\n');
      res.end();
      return;
    }
    const chunks: Buffer[] = [];
    for await (const c of req) chunks.push(c as Buffer);
    res.writeHead(201, { 'content-type': 'application/json', 'x-up': '1' });
    res.end(JSON.stringify({ m: req.method, u: req.url, b: Buffer.concat(chunks).toString(), ct: req.headers['content-type'] ?? null }));
  });
  await new Promise<void>((r) => upstream.listen(0, '127.0.0.1', () => r()));
  const upPort = (upstream.address() as any).port;
  const proxy = http.createServer(async (req, res) => {
    try {
      const controller = new AbortController();
      res.on('close', () => { if (!res.writableFinished) controller.abort(); });
      const headers = { 'content-type': req.headers['content-type'] || 'application/json' };
      const up = await fetch(new URL(req.url!, 'http://127.0.0.1:' + upPort), {
        method: req.method, headers, body: ['GET', 'HEAD'].includes(req.method!) ? undefined : req, duplex: 'half', signal: controller.signal,
      } as any);
      const out = Object.fromEntries(up.headers);
      delete out['content-length']; delete out['date']; delete out['connection']; delete out['keep-alive']; delete out['transfer-encoding'];
      if (up.headers.get('content-type')?.includes('text/event-stream')) {
        out['cache-control'] = 'no-cache';
        res.writeHead(up.status, out);
        res.flushHeaders();
        for await (const chunk of up.body as any) if (!res.write(chunk)) await Promise.race([once(res, 'drain'), once(res, 'close')]);
        res.end();
      } else {
        res.writeHead(up.status, out);
        res.end(Buffer.from(await up.arrayBuffer()));
      }
    } catch (error: any) {
      if (res.headersSent) { res.destroy(); return; }
      res.writeHead(502, { 'content-type': 'application/json' });
      res.end(JSON.stringify({ error: error.message }));
    }
  });
  await new Promise<void>((r) => proxy.listen(0, '127.0.0.1', () => r()));
  const base = 'http://127.0.0.1:' + (proxy.address() as any).port;
  const get = await fetch(base + '/x?a=1');
  console.log(get.status, get.headers.get('x-up'), await get.text());
  const post = await fetch(base + '/p', { method: 'POST', headers: { 'content-type': 'text/plain' }, body: 'hello body' });
  console.log(post.status, post.headers.get('x-up'), await post.text());
  const sse = await fetch(base + '/sse');
  console.log(sse.status, sse.headers.get('content-type'), sse.headers.get('cache-control'), JSON.stringify(await sse.text()));
  proxy.close(); upstream.close();
}
